    uid,
    index,
    phase: g.phase,
    planes: pl.planes,
    power: pl.power,
    hand: pl.hand,
    board: pl.board,
    artifacts: pl.artifacts,
    discard: pl.discard,
    deck: pl.deck.length,
    enemyBoard: enemy.board,
    enemyArtifacts: enemy.artifacts,
    enemyDiscard: enemy.discard,
