        artifacts: p.artifacts.map(enrich),
        discard: p.discard.map(enrich),
        exile: (p.exile || []).map(enrich),
        planes: p.planes,
        power: p.power,
        planePlayed: p.planePlayed,
        losses: p.losses,
        mulligan: p.mulligan,
